SET search_path=vcm,pg_catalog;
CREATE TABLE cases(id text PRIMARY KEY,code text NOT NULL UNIQUE,name text NOT NULL,kind text NOT NULL CHECK(kind IN('initiative','event','activity','presence','campaign')),portfolio_id text REFERENCES portfolios(id),responsible_id text REFERENCES principals(id),responsible_label text,protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),state text NOT NULL DEFAULT 'open',rule_version text NOT NULL DEFAULT 'PO-2026.09-v1',state_object_kind text NOT NULL DEFAULT 'case' CHECK(state_object_kind='case'),priority text NOT NULL DEFAULT 'medium' CHECK(priority IN('low','medium','high')),version int NOT NULL DEFAULT 1 CHECK(version>0),demo boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),archived_at timestamptz,FOREIGN KEY(state_object_kind,rule_version,state) REFERENCES state_definitions);
CREATE TRIGGER case_protect BEFORE INSERT ON cases FOR EACH ROW EXECUTE FUNCTION protect_object('case');
CREATE TABLE case_assignments(case_id text NOT NULL REFERENCES cases(id),principal_id text NOT NULL REFERENCES principals(id),function text NOT NULL,valid_from timestamptz NOT NULL DEFAULT now(),valid_until timestamptz,PRIMARY KEY(case_id,principal_id,function),CHECK(valid_until IS NULL OR valid_until>valid_from));
CREATE INDEX assignments_principal_idx ON case_assignments(principal_id);
CREATE TABLE case_organizations(case_id text NOT NULL REFERENCES cases(id),organization_id text NOT NULL REFERENCES organizations(id),role text NOT NULL,PRIMARY KEY(case_id,organization_id,role));
CREATE TABLE case_agreements(case_id text NOT NULL REFERENCES cases(id),agreement_id text NOT NULL REFERENCES agreements(id),PRIMARY KEY(case_id,agreement_id));
CREATE TABLE presence_records(id text PRIMARY KEY,case_id text NOT NULL UNIQUE REFERENCES cases(id),type_catalog_id text NOT NULL DEFAULT 'presence-2026.09-v1',type_code text,validation_status text NOT NULL DEFAULT 'pending' CHECK(validation_status IN('pending','observed','validated')),version int NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(case_id,id),FOREIGN KEY(type_catalog_id,type_code) REFERENCES catalog_entries);
CREATE TABLE activity_records(id text PRIMARY KEY,case_id text NOT NULL UNIQUE REFERENCES cases(id),schema_version text NOT NULL DEFAULT 'p52-2026.09-v1',validation_status text NOT NULL DEFAULT 'pending' CHECK(validation_status IN('pending','observed','validated')),version int NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(case_id,id));
CREATE TABLE field_definitions(schema_version text NOT NULL,field_key text NOT NULL,label text NOT NULL,group_name text NOT NULL,value_type text NOT NULL CHECK(value_type IN('text','number','money','date','references')),unit text,multiple boolean NOT NULL DEFAULT false,classification boolean NOT NULL DEFAULT false,PRIMARY KEY(schema_version,field_key));
CREATE TABLE case_fields(case_id text NOT NULL REFERENCES cases(id),field_key text NOT NULL,schema_version text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('confirmed','partial','pending','conflict')),observation text NOT NULL DEFAULT '',selected_assertion_id text,PRIMARY KEY(case_id,field_key),FOREIGN KEY(schema_version,field_key) REFERENCES field_definitions);
CREATE TABLE sources(id text PRIMARY KEY,case_id text NOT NULL REFERENCES cases(id),name text NOT NULL,channel text NOT NULL CHECK(channel IN('web','legacy','whatsapp','telegram')),actor_id text NOT NULL REFERENCES principals(id),captured_at timestamptz NOT NULL DEFAULT now(),external_reference text,UNIQUE(case_id,id));
CREATE TABLE field_assertions(id text PRIMARY KEY,case_id text NOT NULL,field_key text NOT NULL,source_id text NOT NULL,actor_id text NOT NULL REFERENCES principals(id),captured_at timestamptz NOT NULL DEFAULT now(),value_type text NOT NULL,text_value text,number_value numeric,money_value bigint CHECK(money_value>=0),date_value date,references_value jsonb,FOREIGN KEY(case_id,field_key) REFERENCES case_fields,FOREIGN KEY(case_id,source_id) REFERENCES sources(case_id,id),UNIQUE(case_id,field_key,id),CHECK(num_nonnulls(text_value,number_value,money_value,date_value,references_value)=1),CHECK((value_type='text' AND text_value IS NOT NULL) OR (value_type='number' AND number_value IS NOT NULL AND number_value>=0) OR (value_type='money' AND money_value IS NOT NULL) OR (value_type='date' AND date_value IS NOT NULL) OR (value_type='references' AND jsonb_typeof(references_value)='array')));
ALTER TABLE case_fields ADD CONSTRAINT selected_assertion_same_field FOREIGN KEY(case_id,field_key,selected_assertion_id) REFERENCES field_assertions(case_id,field_key,id);
CREATE FUNCTION assertion_type() RETURNS trigger LANGUAGE plpgsql SET search_path=vcm,pg_catalog AS $$ DECLARE t text; BEGIN SELECT d.value_type INTO t FROM case_fields f JOIN field_definitions d ON d.schema_version=f.schema_version AND d.field_key=f.field_key WHERE f.case_id=NEW.case_id AND f.field_key=NEW.field_key; IF t IS DISTINCT FROM NEW.value_type THEN RAISE EXCEPTION 'Field type mismatch' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER assertion_type_check BEFORE INSERT ON field_assertions FOR EACH ROW EXECUTE FUNCTION assertion_type();
CREATE TRIGGER assertion_immutable BEFORE UPDATE OR DELETE ON field_assertions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE field_resolutions(id text PRIMARY KEY,case_id text NOT NULL,field_key text NOT NULL,selected_assertion_id text NOT NULL,actor_id text NOT NULL REFERENCES principals(id),reason text NOT NULL CHECK(length(trim(reason))>0),resolved_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(case_id,field_key,selected_assertion_id) REFERENCES field_assertions(case_id,field_key,id));
CREATE TABLE resolution_assertions(resolution_id text NOT NULL REFERENCES field_resolutions(id),assertion_id text NOT NULL REFERENCES field_assertions(id),PRIMARY KEY(resolution_id,assertion_id));
CREATE TRIGGER resolution_immutable BEFORE UPDATE OR DELETE ON field_resolutions FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE document_references(id text PRIMARY KEY,name text NOT NULL,provider text NOT NULL DEFAULT 'reference',external_id text,url text,document_version text,checksum text,protected_object_id text NOT NULL UNIQUE REFERENCES protected_objects(id),version int NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER document_protect BEFORE INSERT ON document_references FOR EACH ROW EXECUTE FUNCTION protect_object('document');
CREATE UNIQUE INDEX document_external_idx ON document_references(provider,external_id) WHERE external_id IS NOT NULL;
CREATE TABLE evidences(id text PRIMARY KEY,case_id text NOT NULL REFERENCES cases(id),document_id text REFERENCES document_references(id),source_id text NOT NULL,name text NOT NULL,review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN('pending','verified','rejected')),version int NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(case_id,id),FOREIGN KEY(case_id,source_id) REFERENCES sources(case_id,id));
CREATE TABLE evidence_reviews(id text PRIMARY KEY,evidence_id text NOT NULL REFERENCES evidences(id),evidence_version int NOT NULL CHECK(evidence_version>0),reviewer_id text NOT NULL REFERENCES users(principal_id),result text NOT NULL CHECK(result IN('verified','rejected')),reason text NOT NULL CHECK(length(trim(reason))>0),reviewed_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER evidence_review_immutable BEFORE UPDATE OR DELETE ON evidence_reviews FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE agreement_documents(agreement_id text NOT NULL REFERENCES agreements(id),document_id text NOT NULL REFERENCES document_references(id),PRIMARY KEY(agreement_id,document_id));
CREATE TABLE field_assertion_references(assertion_id text NOT NULL REFERENCES field_assertions(id),organization_id text REFERENCES organizations(id),agreement_id text REFERENCES agreements(id),evidence_id text REFERENCES evidences(id),CHECK(num_nonnulls(organization_id,agreement_id,evidence_id)=1),UNIQUE NULLS NOT DISTINCT(assertion_id,organization_id,agreement_id,evidence_id));

